-- Apply to an empty project or an inspected, backed-up database. Collisions fail closed.
create type public.staff_role as enum ('super_admin','product_manager','order_manager','customer_support');
create type public.order_state as enum ('pending','confirmed','preparing','shipped','delivered','cancelled','returned');
create table public.profiles(id uuid primary key references auth.users on delete cascade, display_name text not null default '' check(length(display_name)<=100), created_at timestamptz not null default now());
create table public.user_roles(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users on delete cascade, role public.staff_role not null,unique(user_id,role));
create table public.customers(id uuid primary key references auth.users on delete cascade,active boolean not null default true,created_at timestamptz not null default now());
create table public.addresses(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users on delete cascade,city text not null check(length(city) between 1 and 100),address text not null check(length(address) between 1 and 500));
create table public.categories(id uuid primary key default gen_random_uuid(),slug text unique not null check(slug ~ '^[a-z0-9-]+$'),name_ar text not null,name_fr text not null,name_en text not null);
create table public.products(id uuid primary key default gen_random_uuid(),sku text unique not null check(length(sku) between 1 and 80),category_id uuid references public.categories,name_ar text not null,name_fr text not null,name_en text not null,desc_ar text not null default '',desc_fr text not null default '',desc_en text not null default '',price numeric(10,2) not null check(price>0),sale_price numeric(10,2) check(sale_price>0 and sale_price<price),stock integer not null default 0 check(stock>=0),active boolean not null default false,published boolean not null default false,featured boolean not null default false,sold integer not null default 0 check(sold>=0),tier_two numeric(5,2) not null default 10 check(tier_two between 0 and 100),tier_three numeric(5,2) not null default 15 check(tier_three between 0 and 100),created_at timestamptz not null default now());
create table public.product_images(id uuid primary key default gen_random_uuid(),product_id uuid not null references public.products on delete cascade,url text not null check(url ~ '^https://'),position integer not null default 0,unique(product_id,url));
create table public.promotions(id uuid primary key default gen_random_uuid(),code text unique not null check(code ~ '^[A-Z0-9_-]{1,40}$'),kind text not null check(kind in ('percent','fixed')),amount numeric(10,2) not null check(amount>0 and (kind='fixed' or amount<=100)),minimum numeric(10,2) not null default 0 check(minimum>=0),usage_limit integer check(usage_limit>0),starts_at timestamptz,ends_at timestamptz,active boolean not null default false,check(ends_at>starts_at));
create table public.site_settings(id boolean primary key default true check(id),brand text not null default 'Ait Alla Cosmetic',phone text not null default '+212617139424' check(phone ~ '^\+?[0-9]{8,15}$'),whatsapp text not null default '212617139424' check(whatsapp ~ '^[0-9]{8,15}$'),shipping_fee numeric(10,2) not null default 0 check(shipping_fee>=0),free_threshold numeric(10,2) check(free_threshold>=0),cod boolean not null default true,wa_confirmation boolean not null default true,hero_url text check(hero_url ~ '^https://'),announcement_ar text,announcement_fr text,announcement_en text,legacy_hero text);
create table public.orders(id uuid primary key default gen_random_uuid(),reference text unique not null default ('AA-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,14))),user_id uuid not null references public.customers,idempotency_key uuid not null,request jsonb not null,status public.order_state not null default 'pending',name text not null,phone text not null,city text not null,address text not null,instructions text not null default '',subtotal numeric(12,2) not null,discount numeric(12,2) not null,shipping numeric(10,2) not null,total numeric(12,2) not null check(total=subtotal-discount+shipping and total>=0),tracking text not null default '',created_at timestamptz not null default now(),unique(user_id,idempotency_key));
create table public.order_items(id uuid primary key default gen_random_uuid(),order_id uuid not null references public.orders,product_id uuid not null references public.products,name_ar text not null,name_fr text not null,name_en text not null,quantity integer not null check(quantity>0),unit_price numeric(10,2) not null,line_total numeric(12,2) not null,unique(order_id,product_id));
create table public.promotion_usage(id uuid primary key default gen_random_uuid(),promotion_id uuid not null references public.promotions,order_id uuid unique not null references public.orders);
create table public.reviews(id uuid primary key default gen_random_uuid(),product_id uuid not null references public.products on delete cascade,user_id uuid not null references auth.users on delete cascade,rating integer not null check(rating between 1 and 5),body text not null check(length(body) between 1 and 1500),approved boolean not null default false,created_at timestamptz not null default now(),unique(product_id,user_id));
create table public.wishlists(id uuid primary key default gen_random_uuid(),user_id uuid not null unique references auth.users on delete cascade);
create table public.wishlist_items(id uuid primary key default gen_random_uuid(),wishlist_id uuid not null references public.wishlists on delete cascade,product_id uuid not null references public.products on delete cascade,unique(wishlist_id,product_id));
create table public.inventory_movements(id uuid primary key default gen_random_uuid(),product_id uuid not null references public.products,quantity integer not null check(quantity<>0),reason text not null,order_id uuid references public.orders,actor uuid references auth.users,created_at timestamptz not null default now());
create table public.order_status_history(id uuid primary key default gen_random_uuid(),order_id uuid not null references public.orders,status public.order_state not null,created_at timestamptz not null default now());
create table public.order_notes(id uuid primary key default gen_random_uuid(),order_id uuid not null references public.orders,note text not null check(length(note) between 1 and 2000),actor uuid not null default auth.uid(),created_at timestamptz not null default now());
create table public.admin_activity_logs(id uuid primary key default gen_random_uuid(),actor uuid,resource text not null,operation text not null,record_key text,created_at timestamptz not null default now());
create index products_catalog on public.products(category_id,price) where active and published;
create index orders_user_time on public.orders(user_id,created_at desc);
create index orders_status_time on public.orders(status,created_at desc);
create index movement_product on public.inventory_movements(product_id,created_at desc);
create index history_order on public.order_status_history(order_id,created_at);
create index usage_promotion on public.promotion_usage(promotion_id);
